'use strict';
/* tier 是针对 fit 中构筑的强度，不是跨职业的全局排名。 */
const gearSource=url=>'https://bg3.wiki/wiki/'+url;
const addGear=(id,name,act,slot,tier,place,effect,steps,risk,url,fit=[],competition)=>GEAR.push({id,name,act,slot,tier,type:slot,place,effect,steps,acquisition:steps,risk,missRisk:risk,url,fit,version:contentVersion.label,checkedAt:contentVersion.checkedAt,sources:[gearSource(url)],...(competition?{competition}:{} )});
ACT_ONE_GEAR_BASELINE.extraGear.forEach(row=>{
  const [id,name,nameEn,regionId,slot,rarity,place,effect,steps,risk,fit,recommendedLevel,url]=row;
  GEAR.push({id,name,nameEn,act:1,regionId,slot,type:slot,rarity,tier:rarity==='非常稀有'?'强力':'过渡',place,effect,steps,acquisition:steps,branch:'按当前存档的商人、任务与阵营条件取得；互斥条件以获取说明为准。',risk,missRisk:risk,fit,recommendedLevel,url,version:'Patch 8 + Hotfix',checkedAt:'2026-09-20',sources:[gearSource(url)]});
});
GEAR.forEach(g=>{g.slot=g.type.split(' · ')[0];g.tier=['boots','gloves','pike','flinging'].includes(g.id)?'核心':['robe','luminous'].includes(g.id)?'强力':g.tier||'过渡';g.fit=({pike:['giant'],flinging:['giant'],gloves:['giant'],boots:['open-hand'],cloth:['open-hand','bard','ranger','rogue','druid'],robe:['hexblade','sorcerer','bard'],luminous:['light','tempest']})[g.id]||g.fit||[];g.version=contentVersion.label;g.checkedAt=contentVersion.checkedAt;g.sources=[gearSource(g.url)];});
addGear('dex-gloves','敏捷手套',1,'手套','强力','养育间 · 军需官阿杰克尼尔·吉拉','将敏捷设为18，并使攻击骰+1；能把属性点留给力量、感知或魅力。','在养育间仍可交易时购买。','占用手套位；敏捷已18以上时价值下降。','Gloves_of_Dexterity',['open-hand','giant','paladin']);
addGear('spellsparkler','法术火花',1,'武器','强力','沃金休眠地 · 救出弗洛瑞克后','法术或戏法造成伤害会获得闪电充能；多段法术收益较高。','完成火场救援后，从三件奖励中选择。','三选一奖励，不能正常同时取得其余两件。','The_Spellsparkler',['wizard','sorcerer','hexblade']);
addGear('phalar','法拉·阿鲁维',1,'武器','强力','幽暗地域 · 塞伦涅哨站附近','歌唱或尖啸提供团队增益／减益，是团队工具。','探索区域，互动拔出石中剑。','启动效果需要动作；不要只按面板伤害判断它。','Phalar_Aluve',['bard','fighter','paladin']);
addGear('adamantine','精金板条甲',1,'护甲','强力','复仇之炉 · 精金熔炉','高护甲与抗暴击，适合早中期重甲前排。','取得秘银矿、板条甲模具后，在熔炉制造。','秘银矿数量有限，做它便少一份其他精金装备材料。','Adamantine_Splint_Armour',['fighter','paladin','tempest']);
addGear('night-walkers','解离夜行靴',1,'鞋履','强力','复仇之炉 · 复仇者涅雷','免疫部分地表限制并提供迷踪步，泛用性很高。','让涅雷死亡并从可到达的尸体上搜取；支持其存活的路线不会自动获得。','涅雷被困事件有触发式时限；若他存活、尸体落入熔岩或无法搜取，就不能承诺取得。','Disintegrating_Night_Walkers',['fighter','paladin','wizard','tempest']);
addGear('undermountain','低语深地之王的短剑',1,'武器','强力','养育间 · 军需官阿杰克尼尔·吉拉','提高暴击相关收益并改善低伤害骰，适合作副手或灵巧武器。','在军需官商店购买。','不是所有角色都适合双持或灵巧武器。','Knife_of_the_Undermountain_King',['rogue','ranger','bard']);
addGear('blood-lathander','洛山达之血',1,'武器','强力','养育间下方密室','+3钉头锤、光照与一次日光束，面对亡灵和邪魔特别舒服。','解开修道院的黎明主宰者线索取得徽记，再开启密室底座。','强行拿取会触发危险机关，先做徽记路线更稳。','The_Blood_of_Lathander',['light','tempest','paladin']);
addGear('holy-lance-helm','圣枪头盔',1,'头盔','强力','瑰晨修道院 · 屋顶东侧彩绘箱','体质豁免+1；敌人的攻击未命中佩戴者时，须通过敏捷豁免，否则承受1d4光耀伤害。','从巨鹰巢东侧跨越窄隙，在上层壁龛的彩绘箱中取得。','需要中甲熟练；触发依赖敌人未命中且通过固定豁免仍可免伤。','Holy_Lance_Helm',['light','tempest']);
addGear('unseen-menace','隐形威胁',1,'武器','强力','养育间 · 军需官阿杰克尼尔·吉拉','隐形时攻击具有优势且19即可重击；一次未命中后会暂时失去隐形。','在养育间仍中立、军需官仍可交易时购买。','是双手长矛；投掷不应用其隐形武器被动，未命中会中断优势循环。','Unseen_Menace',['fighter','paladin']);
addGear('soulbreaker','灵魂破碎者巨剑',1,'武器','强力','养育间 · 队长房 · 基斯拉克·特蕾津','+2先攻，并提供可造成额外心灵伤害与尝试震慑的灵魂破碎者动作；吉斯洋基持用时另加心灵伤害。','队长特蕾津死亡且尸体可搜取时取得。','和平取得吉斯碎片或让队长开屏障不会自动获得；种族附伤需要吉斯洋基条件。','Soulbreaker_Greatsword',['fighter','paladin']);
addGear('strange-conduit','奇异导管戒指',1,'戒指','强力','养育间 · 审判官房 · 优雅箱','维持法术专注时，武器攻击额外造成1d4心灵伤害。','审判官房右侧走廊的优雅箱内取得。','只强化武器攻击而非徒手攻击；为了附伤硬维持低价值专注可能得不偿失。','Strange_Conduit_Ring',['fighter','ranger','bard']);
addGear('skinburster','剥皮者',1,'武器','强力','养育间 · 审判官房展示区','这把+1长戟每次造成近战伤害时获得2回合力场导管，用连续命中积累减伤。','在审判官房展示柜旁找到并拾取。','需要长戟熟练与双手栏位；离开房间前必须实际拾取，不是击败审判官自动奖励。','The_Skinburster',['fighter','paladin']);
addGear('diadem-arcane-synergy','奥术协同王冠',1,'头盔','强力','养育间 · 审判官房 · 杰雷扎斯','对生物施加状态时获得2回合奥术协同，让武器伤害加入施法关键属性调整值。','击败审判官随从杰雷扎斯后从其身上搜取。','触发依赖实际施加状态；页面记录有特殊触发行为，构筑应按战斗日志核对。','Diadem_of_Arcane_Synergy',['bard','hexblade','paladin']);
addGear('risky-ring','风险之戒',2,'戒指','强力','月出之塔 · 阿拉吉·奥布洛德拉','攻击骰获得优势，代价是豁免劣势；适合急需命中的输出手。','月出之塔尚可交易时向阿拉吉购买。','常吃控制、需要做豁免的角色代价很大。','Risky_Ring',['ranger','rogue','giant','fighter']);
addGear('darkfire','黑火短弓',2,'武器','强力','终焉光芒旅店 · 达蒙','提供火焰／寒冷抗性与急速术，即使不射箭也有价值。','在达蒙存活并抵达旅店时购买。','急速术需专注，断专注会吃迟缓。','Darkfire_Shortbow',['fighter','paladin','ranger','bard']);
addGear('stormy','风暴喧嚣之靴',2,'鞋履','强力','终焉光芒旅店 · 奥姆隆','施加状态时积累雷鸣震颤，配合光耀法球或控制流。','与奥姆隆交易购买。','单纯平砍角色收益有限。','Boots_of_Stormy_Clamour',['light','tempest']);
addGear('belligerent','好战天空手套',2,'手套','强力','雷斯文镇 · 审判官处附近宝箱','雷鸣、闪电或光耀伤害可叠加雷鸣震颤。','探索雷斯文镇审讯相关区域取得。','只推荐给稳定打这三类伤害的角色。','Gloves_of_Belligerent_Skies',['light','tempest']);
addGear('callous','冷酷光芒之戒',2,'戒指','强力','莎尔试炼场 · 巴尔萨泽附近宝库','对被照亮目标追加光耀伤害，适合有稳定光源的多段攻击。','进入巴尔萨泽前哨附近宝库，开启华丽宝箱。','宝库上锁且开锁难度较高；目标须被照亮，暗处战斗收益下降。','Callous_Glow_Ring',['light','open-hand','ranger']);
addGear('arcane-acuity','奥术敏锐头盔',2,'头盔','核心','雷斯文镇 · 梅森公会地下室','武器伤害叠加奥术敏锐，使后续法术更难被豁免。','进地下室，处理门锁和陷阱后开镀金宝箱。','适合先命中再用附赠动作控场，不适合纯法术开场。','Helmet_of_Arcane_Acuity',['bard','hexblade']);
addGear('mystic-scoundrel','神秘恶棍之戒',3,'戒指','核心','马戏团阿卡比传送的丛林区域','武器命中后可用附赠动作施放惑控或幻术，和奥术敏锐头盔形成控制闭环。','赢得阿卡比的“头奖”后，在传送区域背包中寻找。','只影响惑控／幻术，不是所有法术。','Band_of_the_Mystic_Scoundrel',['bard','hexblade']);
addGear('soul-catching','灵魂捕捉手套',3,'手套','核心','希望之邸 · 击败拉斐尔并救下希望','徒手攻击额外造成 1d10 力场伤害，体质 +2（最高 20）；徒手命中后每回合可选恢复 10 点生命，或在下次攻击掷骰与豁免获得优势。','救出希望后击败拉斐尔，且希望在战后存活时由她奖励。','需要先进入希望监狱、使用奥菲斯之锤解除束缚并完成拉斐尔战；与敏捷手套等过渡件竞争，但仍是徒手流终盘核心。','Gloves_of_Soul_Catching',['open-hand']);
addGear('vest-soul','灵魂复苏背心',3,'护甲','强力','下城区 · 巫术用品','徒手攻击后的反应与防御效果适合高机动武僧。','推进巫术用品相关区域后向对应商人购买。','不是力量药武僧唯一毕业选择。','Vest_of_Soul_Rejuvenation',['open-hand']);
addGear('nyrulna','尼鲁纳',3,'武器','核心','马戏团阿卡比传送的丛林区域','+3会回归的三叉戟；投掷会造成雷鸣爆炸。','阿卡比传送后，在出口附近的上锁彩绘箱取得。','爆炸会伤及友军，近战贴脸时要谨慎。','Nyrulna',['giant']);
addGear('giantslayer','博德安巨人杀手',3,'武器','核心','巨龙圣所 · 安苏','传说 +3 巨剑；每次命中使力量调整值伤害翻倍，对大型、巨型和超巨型生物攻击具有优势。每短休可进入巨人形态，获得 27 临时生命、力量检定／豁免优势与武器额外 1d6 伤害。','完成飞龙之路四项试炼进入巨龙圣所，击败安苏后从其尸体搜取（约 X:633、Y:-989）。','巨人杀手不适合投掷攻击，力量调整值翻倍也不作用于投掷；巨人形态与体型类效果共享冲突规则，且双手武器栏会放弃盾牌。','Balduran%27s_Giantslayer',['fighter','paladin','barbarian']);
addGear('markoheshkir','马克赫什基尔',3,'武器','核心','拉玛吉斯高塔 · 下层奥术屏障','+2 法杖，法术攻击与法术豁免难度 +1；奥术电池让下一次法术不消耗法术位，克雷斯卡的恩惠可选择元素增益。','从巫术杂货店传送至拉玛吉斯高塔，下层按“下方”按钮；用识破隐形发现控制杆，并通过 DC20 奥秘检定解除屏障取得。','两个控制杆均有失败后锁定尝试与解离术陷阱；元素恩惠要按当天战斗选择，卸下装备会失去它。','Markoheshkir',['wizard','sorcerer','tempest','light']);
addGear('weave-robe','魔网长袍',3,'服装','核心','拉玛吉斯高塔 · 下层奥术屏障','AC10 服装且额外 +2 AC，法术攻击与法术豁免难度 +1；成功通过豁免时恢复 1d6 生命。','与马克赫什基尔同在拉玛吉斯高塔下层：用识破隐形发现控制杆，通过 DC20 奥秘检定解除另一侧奥术屏障。','两个奖励各有独立屏障与控制杆；失败的角色会失去再次解除同一控制杆的机会，先让奥秘高的角色操作。','Robe_of_the_Weave',['wizard','sorcerer','hexblade','warlock','cleric','druid']);
addGear('bhaalist','巴尔信徒护甲',3,'轻甲','核心','下城区 · 谋杀法庭 · 阿巴济戈的回声','AC14 轻甲；3 米内敌人获得穿刺易伤（免疫者除外），并使先攻 +2，是穿刺队最强的增伤核心之一。','完成谋杀法庭试炼并接受“成为巴尔的邪恶刺客”后，向法庭内的商人“阿巴济戈的回声”购买。','商店与护甲均锁定在邪恶刺客路线，包含重大的剧情与阵营代价；灵光要求持有者贴近目标，远程穿刺队需用走位维持覆盖。','Bhaalist_Armour',['rogue','ranger','fighter','paladin','bard']);
addGear('dead-shot','致命一击',3,'武器','强力','风暴海岸军械库 · 菲茨','+2 长弓，远程攻击的暴击阈值降低 1，且非劣势时远程攻击掷骰获得双倍熟练加值。','在下城区中央墙传送点附近的风暴海岸军械库向菲茨购买（约 X:-36、Y:-83）。','命中优势仅在不处于劣势时生效；与贡德信赖、泰坦弦弓竞争主弓位，但暴击流可稳定利用阈值降低。','The_Dead_Shot',['ranger','bard','rogue']);
addGear('gontr','贡德信赖',3,'武器','核心','钢铁卫士铸造厂 · 控制中心 · 钢铁卫士泰坦','传说 +3 长弓；命中可能施加一回合“引导箭”，每长休可施放天界加速；每短休的“天界之光箭”命中后使本弓远程攻击额外 +1d4 光耀。','在铸造厂控制中心击败钢铁卫士泰坦后搜取。','不要用“萎缩”状态击杀泰坦，否则可能不掉落；引导箭只持续一回合并在持弓者回合结束时消失，需安排队伍攻击顺序。','Gontr_Mael',['ranger','bard','fighter','rogue']);
addGear('amulet-health','高等健康护符',3,'护符','强力','希望之邸 · 拉斐尔私藏区域','将体质设为23，显著提高生命与专注豁免。','探索希望之邸私藏区域，处理机关取得。','全队都想要，优先给最需要维持专注或体质薄弱者。','Amulet_of_Greater_Health',['wizard','sorcerer','tempest','light','hexblade','druid'],'全队通常只会有一件；优先给承担关键专注、体质原本偏低的角色。');
addGear('titanstring','泰坦弦弓',1,'武器','强力','散塔林会藏身处 · 布雷姆','让力量调整值加入远程伤害；力量来源充足时是弓手的早期强势选择。','先与扎瑞斯形成友好结果以解锁布雷姆特殊库存：常见安全路线是救下鲁根后不碰货物，让鲁根携未开的箱子带回；若两名代理人死亡，则亲手把未开的箱子交给扎瑞斯。其他散塔林会分支只按扎瑞斯是否友好、库存是否实际开放来条件化处理，再向布雷姆购买。','打开箱子后再交给扎瑞斯会使她与散塔林会敌对；打开箱子的后果在交付或被发现时结算，不笼统视为当场失去商店。没有力量来源时收益也会下降。','Titanstring_Bow',['fighter','ranger','bard'],'与其他主弓手竞争；只有能稳定取得力量加成的角色才应优先拿。');
addGear('punch-drunk','醉拳混蛋',2,'武器','核心','雷斯文镇 · 衰败月亮酒馆 · 西侧后方上锁宝箱','醉酒时获得额外雷鸣伤害，并让周围生物承受相应雷鸣风险，服务醉拳主题近战。','从酒馆西侧后方的上锁宝箱取得；无需击败西索巴德·索姆。','必须维持醉酒才能发挥效果；范围雷鸣会波及贴身队友。西索巴德·索姆的遭遇是可选风险，不是取得此武器的前提。','Punch-Drunk_Bastard',['drunken']);
addGear('cunning-brume','狡诈雾霭斗篷',2,'斗篷','强力','终焉光芒旅店 · 马蒂斯','脱离后制造迷雾，给暗影武僧提供断视线与重新潜行窗口。','在终焉光芒旅店仍可交易时向马蒂斯购买。','需要附赠动作脱离；马蒂斯是否可交易取决于提夫林路线与此前事件。','Cloak_of_Cunning_Brume',['shadow-monk','rogue']);
addGear('whispering-promise','低语承诺',1,'戒指','核心','翠绿林地／地精营地 · 沃罗或格拉特','治疗目标会获得祝福效果，适合用低成本群体治疗触发队伍增益。','沃罗在林地时于对话左下角进入交易；若未取得，沃罗被俘后同一枚戒指会进入格拉特库存，获救入营后也可再向沃罗交易。','同一周目只有这一枚；沃罗与格拉特的移动、敌对或死亡会改变购买窗口。','The_Whispering_Promise',['healer','cleric','bard'],'治疗辅助与其他需要戒指栏的构筑会竞争；优先给能频繁、小额治疗全队的人。');
addGear('hellrider-pride','地狱骑士的傲慢',1,'手套','强力','翠绿林地 · 泽夫洛','治疗目标获得刃甲，能把群体治疗转化为短时物理减伤。','完成“调查卡哈”或“杀死卡哈”的对应奖励条件后向泽夫洛领取；也可从他身上偷取或在其死亡后搜取。','不是单纯保护林地的结算奖励；泽夫洛存活与任务交付顺序会影响和平取得方式。','Hellrider%27s_Pride',['healer','cleric']);
addGear('aid-comfort','援助与慰藉之靴',1,'鞋履','强力','地精营地 · 格拉特','治疗他人时给予临时生命，适合生命牧师或辅助诗人补强容错。','在地精营地仍能与格拉特交易时购买。','商人敌对或死亡会失去稳定购买渠道；临时生命不与其他来源叠加。','Boots_of_Aid_and_Comfort',['healer','cleric','bard']);
addGear('moonbasking','月照护甲',3,'轻甲','核心','下城区下水道 · 无声忏悔者巴雷基','野性变形后获得 22 点临时生命；临时生命存在时获得伤害减免 1。护甲另给 +2 AC，且对法术豁免具有优势，效果在野性变形中保留。','从地下城遗迹传送点向西进入巴雷基所在凹室，在他仍可交易时购买。','核心收益只在野性变形后触发；需轻甲熟练，且结束变形会失去临时生命与减伤，非月亮德鲁伊通常不值得占身体栏。','Armour_of_Moonbasking',['moon-druid']);
addGear('shapeshifter-boon','变形者的恩赐之戒',2,'戒指','强力','终焉光芒旅店 · 怪牛','变形或伪装时提高全部属性检定，给常驻形态、侦察和对话变形提供工具收益。','在终焉光芒旅店与怪牛互动并满足交易／取得条件。','怪牛跨章节的存活与路线会影响可取得性；它不直接提高野性形态的攻击伤害。','Shapeshifter%27s_Boon_Ring',['moon-druid','druid']);
addGear('hood-weave','魔网兜帽',3,'头盔','强力','下城区 · 菲尔格雷夫宅邸 · 神秘卡里翁','法术攻击掷骰与法术豁免 DC 均 +2，是控场施法者的头部毕业选项。','在菲尔格雷夫宅邸仍可交易时向神秘卡里翁购买；选择击败他后也可从尸体搜取。','任务线与存活状态会改变交易机会；+2 命中与 DC 很强，但不会让控制法术变成必中。','Hood_of_the_Weave',['wizard','sorcerer','warlock','druid'],'主控法师、术士和邪术师会竞争；优先给最常以豁免法术决定战局的角色。');
addGear('spellcrux','法术水晶护符',2,'护符','强力','月出之塔 · 典狱长','可恢复一个已消耗的法术位，适合依赖高环控制、召唤或爆发的施法者。','和平进入月出之塔后先侦察监狱；处理典狱长并搜刮。','监狱救援与第二章终局会锁定区域；恢复法术位次数有限，别当作无限资源。','Spellcrux_Amulet',['wizard','sorcerer','warlock','druid','cleric'],'与高等健康护符竞争护符栏；优先给缺少长休、但需要多一发关键高环法术的人。');
addGear('ring-salving','疗愈之戒',1,'戒指','强力','幽暗地域 · 蕈人栖息地 · 奥梅鲁姆','治疗其他生物时额外恢复 2 点生命，保留治疗触发辅助的戒指栏位。','完成“帮助奥梅鲁姆调查寄生虫”后解锁其交易，再在蕈人栖息地向他购买。','必须先完成奥梅鲁姆的调查任务；只提高实际治疗量，不能替代低语承诺提供的祝福效果。','Ring_of_Salving',['healer','cleric','bard']);
